/* Plain-language definitions. full expands acronyms; learn is the primary
 * local lesson, link an optional external reference. Keys are stable anchors. */
(function () {
  "use strict";
  var WGSM = window.WGSM;
  WGSM.v2terms = WGSM.v2terms || {};
  var terms = {
    dna: { term: "DNA", full: "Deoxyribonucleic acid", aliases: [],
      short: "DNA — Deoxyribonucleic acid: the molecule that stores inherited information as a sequence of four chemical bases, A, C, G and T.",
      more: "Sequencing estimates the order of those bases. A DNA sequence alone does not describe your health, experiences or identity.", learn: "learn-dna.html#dna" },
    genome: { term: "Genome", aliases: ["genome", "genomes", "whole genome"],
      short: "A genome is the complete set of DNA sequences in an organism, including chromosomes and mitochondrial DNA.",
      more: "A human reference has about 3.1 billion bases in one set of nuclear chromosomes. A whole-genome test aims broadly across it, but cannot read every position equally well.", learn: "learn-dna.html#chromosomes" },
    chromosome: { term: "Chromosome", aliases: ["chromosome", "chromosomes", "autosomes", "autosomal"],
      short: "A chromosome is a long DNA molecule packaged with proteins. Human nuclear chromosomes are numbered 1–22, plus X and Y.",
      more: "Most cells have two copies of chromosomes 1–22, one inherited from each biological parent. Chromosome complements vary; a file's X/Y pattern is not a statement of gender.", learn: "learn-dna.html#chromosomes" },
    gene: { term: "Gene", aliases: ["gene", "genes"],
      short: "A gene is a stretch of DNA used to make a functional RNA molecule; many RNAs provide instructions for making a protein.",
      more: "Variants can affect a gene's product or its regulation. Being inside a gene does not by itself make a variant harmful.", learn: "learn-dna.html#genes" },
    allele: { term: "Allele", aliases: ["allele", "alleles"],
      short: "An allele is one version of a DNA sequence at a particular location, such as A or G at one position.",
      more: "A diploid genotype contains two alleles. The reference allele is the one in the chosen reference, not necessarily the most common or healthiest one.", learn: "learn-variants.html#genotype" },
    vcf: { term: "VCF", full: "Variant Call Format", aliases: ["VCFs", "variant call format"],
      short: "VCF — Variant Call Format: a text table of genomic positions, reference and alternative sequences, and sample genotypes.",
      more: "A compressed small-variant whole-genome VCF is often hundreds of MB. Keep it for annotation, but it contains no reads: an unlisted site may be reference, untested or filtered out.", learn: "learn-files.html#vcf",
      link: "https://samtools.github.io/hts-specs/VCFv4.5.pdf" },
    gvcf: { term: "gVCF", full: "Genomic Variant Call Format", aliases: ["gVCFs", "genome VCF", "genomic VCF"],
      short: "gVCF — Genomic Variant Call Format: a VCF that also records non-variant sites or blocks and evidence for reference calls.",
      more: "Use caller-compatible gVCFs for joint genotyping or to distinguish supported reference calls from missing data. Blocks can still be low confidence; this is not proof every base was measured.", learn: "learn-files.html#vcf" },
    bam: { term: "BAM", full: "Binary Alignment Map", aliases: ["BAMs", "BAM file"],
      short: "BAM — Binary Alignment Map: a binary file of sequencing reads, their quality scores and alignment records against a reference.",
      more: "A 30× short-read genome often occupies 60–100 GB. Keep it to inspect read evidence or call variants again; regional access needs its matching .bai or .csi index.", learn: "learn-files.html#bam" },
    cram: { term: "CRAM", full: "Compressed Reference-oriented Alignment Map", aliases: ["CRAMs", "CRAM file"],
      short: "CRAM — Compressed Reference-oriented Alignment Map: a compressed read-alignment format that often encodes bases relative to a reference.",
      more: "Often tens of GB for a 30× genome, depending on quality-score retention and compression. Preserve the exact reference and .crai index; CRAM can be lossless, but some producers discard quality detail.", learn: "learn-files.html#bam",
      link: "https://samtools.github.io/hts-specs/CRAMv3.pdf" },
    fastq: { term: "FASTQ", full: "FASTA with Quality scores", aliases: ["FASTQs", "FASTQ file", "fastq.gz"],
      short: "FASTQ — FASTA with Quality scores: a text file containing each read's name, DNA letters and a quality character for every letter.",
      more: "Short paired-end runs usually have R1 and R2 files, often gzip-compressed. These reads have no genomic coordinates yet; aligning them requires a reference and substantial time and disk.", learn: "learn-files.html#fastq" },
    fasta: { term: "FASTA", full: "FAST-All (sequence format name)", aliases: [".fa", ".fasta"],
      short: "FASTA — FAST-All: a text sequence format in which each record has a name beginning with > followed by DNA, RNA or protein letters.",
      more: "Reference DNA is commonly a FASTA file, about 3 GB uncompressed for a human assembly. It has no per-base quality scores; a consensus FASTA also cannot retain both alleles at every site.", learn: "learn-files.html#reference" },
    index: { term: "Index", aliases: ["index", "indexes", "indexed", ".bai", ".crai", ".tbi", ".csi", ".fai"],
      short: "An index is a companion file mapping genomic regions to locations inside a sequence or alignment file, so tools can jump there directly.",
      more: "BAM uses .bai or .csi, CRAM .crai, compressed VCF .tbi or .csi, and FASTA .fai. Rebuild after changing the data file; aligner reference indexes are different, often many GB.", learn: "learn-files.html#indexes" },
    bed: { term: "BED", full: "Browser Extensible Data", aliases: ["BED file", "BED files"],
      short: "BED — Browser Extensible Data: a text list of intervals, with chromosome, start and end columns.",
      more: "Use it to restrict analysis to selected regions. BED starts at zero and excludes the end: BED 0–100 means bases 1–100 in one-based coordinates. The build must also match.", learn: "learn-reference.html#coordinates" },
    kit: { term: "DNA-test file", aliases: ["DNA-test files", "raw data", "raw-data file", "raw-data files", "kit", "kits", "23andMe", "AncestryDNA"],
      short: "A DNA-test file is a company's downloadable table of marker identifiers, coordinates and genotypes, usually measured with a microarray.",
      more: "23andMe and AncestryDNA chip versions typically test hundreds of thousands of selected positions, not all DNA. WGS Extract can export a compatible table from sequencing; acceptance by a receiving site is not guaranteed.", learn: "learn-files.html#kits" },
    chip: { term: "Microarray", aliases: ["chip", "chips", "microarray", "microarrays"],
      short: "A DNA microarray is a physical chip with probes designed to test particular known DNA variants.",
      more: "Companies use different marker sets and chip versions. It cannot discover arbitrary new variants, and a negative result at tested markers does not rule out a genetic condition.", learn: "learn-sequencing.html#sample" },
    marker: { term: "Marker", aliases: ["marker", "markers"],
      short: "A marker is a DNA location or repeat used as a recognizable feature for comparison, ancestry or a genetic test.",
      more: "Many single-base markers have an rsID. Matching services compare overlapping markers; the number shared limits what a kit-to-kit comparison can show.", learn: "learn-ancestry.html#autosomal" },
    rsid: { term: "rsID", full: "Reference SNP cluster identifier", aliases: ["rsIDs"],
      short: "rsID — Reference SNP cluster identifier: a dbSNP database label such as rs53576 for a reported variant site.",
      more: "It is an identifier, not a medical verdict or a fixed coordinate. One label may involve multiple alleles, and its location depends on the reference assembly.", learn: "learn-variants.html#types" },
    strand: { term: "Strand", aliases: ["strand", "strands", "strand-ambiguous"],
      short: "A DNA strand is one chain of the double helix; A pairs with T on the other chain, and C with G.",
      more: "Marker files can report either strand. A/T and C/G marker pairs are strand-ambiguous: letters alone cannot reveal an orientation mix-up.", learn: "learn-dna.html#dna" },
    reference: { term: "Reference genome", aliases: ["reference genome", "reference genomes", "reference sequence"],
      short: "A reference genome is a named collection of DNA sequences used as a coordinate map for read alignments and variants.",
      more: "It is not a perfect or 'normal' person. Coordinates and read placement depend on the exact assembly; CRAM decoding may require its exact reference sequence.", learn: "learn-reference.html#reference",
      link: "https://www.ncbi.nlm.nih.gov/grc/human" },
    build: { term: "Genome build", aliases: ["genome build", "genome builds", "builds of the reference"],
      short: "A genome build is a particular release of an assembled reference sequence, such as GRCh37 or GRCh38.",
      more: "Sequence corrections and added regions move coordinates. Check the build and sequence dictionary before combining files; renaming chromosomes is not a build conversion.", learn: "learn-reference.html#builds" },
    grch37: { term: "GRCh37", full: "Genome Reference Consortium human build 37", aliases: ["hg19", "build 37"],
      short: "GRCh37 — Genome Reference Consortium human build 37: a human reference assembly released in 2009.",
      more: "Many older files use its coordinates. UCSC hg19 is closely related but not identical in all sequences, especially mitochondria; use the exact reference variant, not just a familiar build label.", learn: "learn-reference.html#builds" },
    grch38: { term: "GRCh38", full: "Genome Reference Consortium human build 38", aliases: ["hg38", "build 38"],
      short: "GRCh38 — Genome Reference Consortium human build 38: the 2013 human reference assembly, widely used by current tools and databases.",
      more: "It corrects and adds sequence relative to GRCh37. Files labelled hg38 or GRCh38 can include different alternate contigs or decoys, so the exact FASTA still matters.", learn: "learn-reference.html#builds" },
    hs37d5: { term: "hs37d5", full: "Human sequence, build 37 with decoy sequences", aliases: [],
      short: "hs37d5 is a GRCh37-based reference FASTA with additional decoy sequences used to improve read placement.",
      more: "Keep the exact file when preserving a CRAM made against it. It is not interchangeable with every reference labelled hg19 or GRCh37.", learn: "learn-reference.html#cram" },
    hs38: { term: "hs38", full: "Human sequence, build 38 reference bundle", aliases: ["hs38d1", "hs38DH"],
      short: "hs38 names a GRCh38-based reference bundle; suffixes such as d1 or DH identify bundles with different extra sequences.",
      more: "Check the bundle's sequence names and checksums, particularly for CRAM decoding. Shared primary-chromosome coordinates do not make bundles identical.", learn: "learn-reference.html#cram" },
    t2t: { term: "T2T-CHM13", full: "Telomere-to-Telomere CHM13 assembly", aliases: ["T2T", "CHM13", "T2T-CHM13 v2.0"],
      short: "T2T — Telomere-to-Telomere: the project that produced the nearly gap-free CHM13 human reference, including previously missing repeat-rich sequence.",
      more: "CHM13 has no Y chromosome; some reference bundles add a separate complete Y from HG002. Check the bundle rather than assuming a 'T2T' label includes Y or GRCh38-compatible coordinates.", learn: "learn-reference.html#builds",
      link: "https://github.com/marbl/CHM13" },
    decoy: { term: "Decoy", aliases: ["decoy", "decoys", "decoy sequences"],
      short: "A decoy is an extra reference sequence that gives otherwise misplaced reads a more suitable alignment target.",
      more: "It can reduce false variants caused by forcing reads onto similar chromosomes. Adding decoys changes the reference bundle and requires matching aligner indexes.", learn: "learn-reference.html#cram" },
    reads: { term: "Read", aliases: ["reads", "raw reads", "short reads", "sequencing reads"],
      short: "A read is one sequencer's estimated sequence of a DNA fragment, recorded as letters with quality scores.",
      more: "Illumina reads are often 150 bases long; long reads may span thousands. A read is evidence, not an error-free copy of your DNA.", learn: "learn-sequencing.html#reads" },
    paired: { term: "Paired-end", aliases: ["paired-end", "paired reads", "read pairs"],
      short: "Paired-end sequencing reads both ends of the same DNA fragment, producing two linked reads.",
      more: "R1 and R2 are usually separate FASTQ files whose records correspond. Do not mix pairs from different samples; their spacing also helps alignment.", learn: "learn-sequencing.html#reads" },
    bp: { term: "bp", full: "Base pair", aliases: ["base pair", "base pairs"],
      short: "bp — Base pair: one paired position in double-stranded DNA, also used to state a DNA sequence's length.",
      more: "1 kb is 1,000 bp and 1 Mb is one million bp. A 2 × 150 bp run reads 150 bases from each end, not necessarily the entire fragment between.", learn: "learn-dna.html#dna" },
    illumina: { term: "Illumina", aliases: [],
      short: "Illumina is a manufacturer of sequencing instruments that typically read many short DNA fragments using fluorescent chemistry.",
      more: "Human whole-genome data often arrives as paired 100–150 base reads. Short reads are accurate per base but can be hard to place uniquely in repeats.", learn: "learn-sequencing.html#platforms" },
    longreads: { term: "Long reads", aliases: ["long reads", "long read", "long-read"],
      short: "Long reads are sequence records spanning thousands to tens of thousands of DNA bases, sometimes much longer.",
      more: "They can bridge repeats, structural variants and distant alleles. Error patterns and suitable caller models differ between PacBio HiFi and Oxford Nanopore.", learn: "learn-sequencing.html#platforms" },
    pacbio: { term: "PacBio HiFi", full: "Pacific Biosciences High-Fidelity reads", aliases: ["PacBio", "HiFi"],
      short: "PacBio HiFi — Pacific Biosciences High-Fidelity reads: long, accurate reads made by repeatedly reading the same circular DNA template.",
      more: "Typical reads span roughly 10–25 kb. They help resolve repeats and phase variants, but need an aligner and caller model suited to HiFi data.", learn: "learn-sequencing.html#platforms" },
    ont: { term: "ONT", full: "Oxford Nanopore Technologies", aliases: ["Oxford Nanopore", "Nanopore", "nanopore"],
      short: "ONT — Oxford Nanopore Technologies: sequencing that estimates DNA bases from electrical signals as molecules pass through tiny pores.",
      more: "Reads can be tens of kb or longer. Basecalling models and chemistry affect accuracy; retained signal or modification tags are needed for some later analyses.", learn: "learn-sequencing.html#platforms" },
    align: { term: "Alignment", aliases: ["align", "aligned", "aligning", "alignment", "realign", "realigned", "realigning"],
      short: "Alignment is the computational placement of each read against similar reference sequence, recording its position and mismatches.",
      more: "It turns FASTQ into alignment records in BAM or CRAM. Whole-genome runs may take hours; ambiguous repeats can still put a read in the wrong place.", learn: "learn-files.html#alignment" },
    bwa: { term: "bwa", full: "Burrows-Wheeler Aligner", aliases: ["BWA", "BWA-MEM", "bwa mem"],
      short: "bwa — Burrows-Wheeler Aligner: software that places DNA reads against a reference; BWA-MEM is its common short-read alignment algorithm.",
      more: "Use it for suitable short-read data with a matching reference index. Long, noisy reads need a different algorithm or tool.", learn: "learn-files.html#alignment" },
    bwamem2: { term: "bwa-mem2", full: "Burrows-Wheeler Aligner, maximal exact match 2", aliases: [],
      short: "bwa-mem2 — Burrows-Wheeler Aligner, maximal exact match 2: optimized software for placing short reads against a reference on CPUs.",
      more: "It targets equivalent alignments with higher throughput. Its reference indexes and memory requirements are larger than original bwa's; check resources before a genome run.", learn: "learn-files.html#alignment" },
    bwamem3: { term: "bwa-mem3", full: "Burrows-Wheeler Aligner, maximal exact match 3", aliases: [],
      short: "bwa-mem3 — Burrows-Wheeler Aligner, maximal exact match 3: a newer short-read alignment program supported by WGS Extract.",
      more: "It reuses bwa-mem2 indexes. Presets and hardware affect speed and output equivalence; do not assume every fast mode produces identical records.", learn: "learn-files.html#alignment" },
    minimap2: { term: "minimap2", aliases: [],
      short: "minimap2 is software for aligning long DNA reads or assembled sequences to a reference.",
      more: "Choose a preset matching PacBio HiFi or Nanopore. The wrong preset can reduce mapping accuracy; indexes also depend on alignment settings.", learn: "learn-files.html#alignment" },
    depth: { term: "Depth", aliases: ["depth", "mean depth", "coverage", "read depth"],
      short: "Read depth is the number of reads covering a position; mean depth averages that number across a region, often written 30×.",
      more: "30× means an average of 30 read observations, not that every base was read 30 times. 'Coverage' can instead mean the fraction reaching a threshold; repeats and some chromosomes have different usable depth.", learn: "learn-sequencing.html#depth" },
    unmapped: { term: "Unmapped reads", aliases: ["unmapped reads", "unmapped"],
      short: "Unmapped reads are read records for which the aligner did not report a reference placement.",
      more: "They may come from low-quality sequence, missing human reference sequence or other organisms. They are not by themselves evidence of infection or contamination.", learn: "learn-sequencing.html#quality" },
    phred: { term: "Phred quality", full: "Phred-scaled error probability", aliases: ["Phred", "base quality", "quality scores", "Q30"],
      short: "Phred quality is a logarithmic error score: Q = −10 log10(P of error), so Q30 corresponds to an estimated error probability of 1 in 1,000.",
      more: "A base quality describes one base estimate, not the certainty of an entire variant call. These are model estimates, not measured error guarantees.", learn: "learn-sequencing.html#quality" },
    mapq: { term: "MAPQ", full: "Mapping quality", aliases: ["mapping quality"],
      short: "MAPQ — Mapping quality: an aligner's Phred-scaled estimate of the chance that a read's placement is wrong.",
      more: "It differs from base quality and genotype quality. Repetitive regions often have low mapping quality; 255 commonly means unavailable, not extraordinarily certain.", learn: "learn-sequencing.html#quality" },
    gq: { term: "GQ", full: "Genotype quality", aliases: ["genotype quality", "Genotype quality"],
      short: "GQ — Genotype quality: a caller's Phred-scaled confidence score for its chosen genotype.",
      more: "GQ20 and GQ30 correspond roughly to modeled error probabilities of 1% and 0.1%. Filtering by GQ helps, but cannot correct a wrong reference, systematic bias or sample mix-up.", learn: "learn-variants.html#confidence" },
    n50: { term: "N50", full: "Length-weighted median sequence length", aliases: ["read N50"],
      short: "N50 is the sequence length at which sequences of that length or longer contain at least half the total bases.",
      more: "A read N50 of 20 kb means half the sequenced bases lie in reads at least 20 kb long. It is not the median read count or a measure of base accuracy.", learn: "learn-sequencing.html#platforms" },
    variant: { term: "Variant", aliases: ["variant", "variants"],
      short: "A variant is a DNA sequence difference described relative to a specified reference, from one base to a large rearrangement.",
      more: "A person typically has millions of small variants. Most are not harmful; being different from the reference does not establish a medical effect.", learn: "learn-variants.html#types" },
    calling: { term: "Variant calling", aliases: ["variant calling", "call variants", "calls variants", "calling variants", "caller", "callers", "variant caller"],
      short: "Variant calling is software's inference of sequence differences and genotypes from read evidence.",
      more: "Callers write VCF or gVCF records and quality fields. Models, ploidy and read technology matter; different callers can disagree on the same reads.", learn: "learn-files.html#calling" },
    genotype: { term: "Genotype", aliases: ["genotype", "genotypes"],
      short: "A genotype is the allele or combination of alleles called at a location, such as A/G for two chromosome copies.",
      more: "In a diploid VCF, 0/1 means one reference and one first alternative allele; 1/1 means two first alternative alleles. A dot means missing, and some regions have only one copy.", learn: "learn-variants.html#genotype" },
    snp: { term: "SNP", full: "Single-nucleotide polymorphism", aliases: ["SNPs"],
      short: "SNP — Single-nucleotide polymorphism: a position where a single DNA base varies in a population.",
      more: "Often used loosely for any single-base variant; SNV is the broader term. A single-base change can be harmless, harmful or uncertain depending on context.", learn: "learn-variants.html#types" },
    snv: { term: "SNV", full: "Single-nucleotide variant", aliases: ["SNVs"],
      short: "SNV — Single-nucleotide variant: a substitution of one DNA base, such as reference A becoming G.",
      more: "An SNV may be rare or common. A marker chip tests selected sites; sequencing can discover changes beyond those sites.", learn: "learn-variants.html#types" },
    indel: { term: "Indel", full: "Insertion or deletion", aliases: ["indel", "indels"],
      short: "Indel — Insertion or deletion: DNA bases added or missing relative to a reference, usually referring to small changes under about 50 bases.",
      more: "Indels in repeats can have several equivalent coordinate descriptions. Normalize before database matching; small size does not imply a small biological effect.", learn: "learn-variants.html#types" },
    sv: { term: "SV", full: "Structural variant", aliases: ["structural variant", "structural variants", "SVs"],
      short: "SV — Structural variant: a larger DNA change, conventionally about 50 bases or more, such as a deletion, duplication, inversion or translocation.",
      more: "Dedicated callers use read depth, split reads or long reads. Some SVs matter medically; an ordinary SNP/indel VCF does not comprehensively test for them.", learn: "learn-variants.html#types" },
    cnv: { term: "CNV", full: "Copy-number variant", aliases: ["CNVs", "copy-number variant", "copy-number variants", "copy number"],
      short: "CNV — Copy-number variant: a DNA segment present in fewer or more copies than expected for that region.",
      more: "Deletions and duplications can change read depth. Uneven sequencing can mimic them, so a depth-based candidate needs additional evidence.", learn: "learn-variants.html#types" },
    str: { term: "STR", full: "Short tandem repeat", aliases: ["STRs", "short tandem repeat", "short tandem repeats", "repeat expansions"],
      short: "STR — Short tandem repeat: a short DNA motif repeated consecutively, such as CAG repeated 20 times.",
      more: "Specialist tools estimate repeat counts; some expansions cause disease. A repeat longer than the reads can be difficult to size, so a result may need a dedicated clinical assay.", learn: "learn-variants.html#types" },
    ystr: { term: "Y-STR", full: "Y-chromosome short tandem repeat", aliases: ["Y-STRs"],
      short: "Y-STR — Y-chromosome short tandem repeat: a repeated DNA motif on the Y chromosome reported as a repeat count.",
      more: "Surname projects compare panels of these counts for paternal-line genealogy. Mutation rates vary, and short-read estimates may not match a dedicated laboratory panel.", learn: "learn-ancestry.html#lineage" },
    deepvariant: { term: "DeepVariant", aliases: [],
      short: "DeepVariant is a machine-learning program that calls small variants and genotypes from aligned sequencing reads.",
      more: "Use a model matching the read technology. It can use supported GPU configurations but still needs CPU work, and it is not a comprehensive structural-variant or medical test.", learn: "learn-files.html#calling" },
    gatk: { term: "GATK", full: "Genome Analysis Toolkit", aliases: ["GATK HaplotypeCaller", "HaplotypeCaller"],
      short: "GATK — Genome Analysis Toolkit: software for sequencing analysis; its HaplotypeCaller infers small variants by locally assembling read sequences.",
      more: "It can create gVCFs for later joint genotyping. Use compatible workflow and reference resources; a lab-standard tool alone does not make a personal run clinical-grade.", learn: "learn-files.html#calling" },
    bcftools: { term: "bcftools", full: "Binary Call Format tools", aliases: [],
      short: "bcftools — Binary Call Format tools: command-line programs for reading, filtering, converting and calling variants in VCF and BCF files.",
      more: "Its mpileup/call workflow calls small variants from aligned reads. Accuracy depends on data and parameters; speed is not a reason to ignore quality checks.", learn: "learn-files.html#calling" },
    samtools: { term: "samtools", full: "Sequence Alignment/Map tools", aliases: [],
      short: "samtools — Sequence Alignment/Map tools: command-line programs for inspecting, sorting, indexing and converting read-alignment files such as BAM and CRAM.",
      more: "Many WGS Extract operations use it underneath. Sorting or indexing changes access to reads; it does not fix a scientifically incorrect alignment.", learn: "learn-files.html#indexes" },
    htslib: { term: "htslib", full: "High-throughput sequencing library", aliases: [],
      short: "htslib — High-throughput sequencing library: reusable software for reading and writing formats such as BAM, CRAM and VCF.",
      more: "samtools and bcftools use it. It is a dependency, not a separate caller or a genome file.", learn: "learn-files.html#indexes" },
    phasing: { term: "Phasing", aliases: ["phasing", "phase", "phased", "unphased"],
      short: "Phasing groups alleles at different positions onto the same chromosome copy.",
      more: "Reads, relatives or population patterns can support phase. A phased 0|1 is not automatically labelled maternal or paternal; phase can break or switch along a chromosome.", learn: "learn-variants.html#phasing" },
    imputation: { term: "Imputation", aliases: ["imputation", "impute", "imputed", "imputing"],
      short: "Imputation statistically estimates unmeasured genotypes using measured markers and a reference panel of other genomes.",
      more: "Useful for arrays or low-depth sequencing, but accuracy depends on allele frequency and panel representation. It is not direct measurement, especially unreliable for rare personal health findings.", learn: "learn-variants.html#phasing" },
    denovo: { term: "De novo", aliases: ["de novo"],
      short: "A de novo variant is a new sequence change in a child that was not inherited as an ordinary allele from either parent.",
      more: "Trio analysis finds candidates, not proof: errors and low-level parental mosaicism can look similar. Confirmation and family context are essential for medical interpretation.", learn: "learn-variants.html#confidence" },
    heteroplasmy: { term: "Heteroplasmy", aliases: ["heteroplasmy", "heteroplasmic"],
      short: "Heteroplasmy is the presence of more than one mitochondrial DNA sequence version in a sample or cell.",
      more: "A 20% level means about a fifth of observed mtDNA molecules carry the allele, subject to measurement bias. Levels differ between tissues; one sample cannot establish a clinical effect.", learn: "learn-ancestry.html#lineage" },
    contamination: { term: "Contamination", aliases: ["contamination", "contaminated"],
      short: "Contamination is unintended DNA from another source mixed into a sample; human-contamination tools estimate DNA from other people.",
      more: "Even a small mixture can distort rare genotypes. Estimates depend on the method and population model; microbial reads and another person's reads are different problems.", learn: "learn-sequencing.html#quality" },
    relatedness: { term: "Relatedness", aliases: ["relatedness", "kinship"],
      short: "Genetic relatedness measures how much inherited DNA two samples share; kinship is a statistical summary of that sharing.",
      more: "It can reveal relatives, duplicate samples or mix-ups. Similar sharing can fit several family relationships, and unexpected results can be sensitive.", learn: "learn-ancestry.html#relatives" },
    ploidy: { term: "Ploidy", aliases: ["ploidy", "diploid", "haploid"],
      short: "Ploidy is the number of chromosome copies at a region: diploid means two, haploid means one.",
      more: "Most autosomal regions are diploid. X/Y copy numbers and their shared pseudoautosomal regions need region-specific handling; an incorrect caller model can create false genotypes.", learn: "learn-variants.html#genotype" },
    zygosity: { term: "Zygosity", aliases: ["heterozygous", "homozygous", "heterozygosity", "zygosity"],
      short: "Zygosity describes whether alleles at a diploid site are the same (homozygous) or different (heterozygous).",
      more: "A/G is heterozygous and G/G homozygous. A one-copy region is hemizygous instead; zygosity alone does not determine a variant's health effect.", learn: "learn-variants.html#genotype" },
    titv: { term: "Ti/Tv", full: "Transition-to-transversion ratio", aliases: ["transitions to transversions", "transitions", "transversions"],
      short: "Ti/Tv — Transition-to-transversion ratio: the count of A↔G and C↔T substitutions divided by the count of other base substitutions.",
      more: "Whole-genome small-variant sets often have a ratio near 2. Atypical values can prompt review, but expected values depend on regions, filtering and variant selection.", learn: "learn-variants.html#confidence" },
    jointcalling: { term: "Joint calling", aliases: ["joint calling", "joint-called", "joint genotyping"],
      short: "Joint genotyping assigns genotypes to several samples at a shared set of candidate variant sites, often using per-sample gVCFs.",
      more: "Useful for family and cohort comparisons. Inputs must use compatible builds and caller workflows; combining tables is not the same as joint genotyping.", learn: "learn-files.html#vcf" },
    haplogroup: { term: "Haplogroup", aliases: ["haplogroup", "haplogroups"],
      short: "A haplogroup is a named branch on a genetic lineage tree, here based on shared Y-chromosome or mitochondrial variants.",
      more: "It describes one direct ancestral line, not all ancestors or ethnicity. Confidence depends on covered defining markers and the version of the tree.", learn: "learn-ancestry.html#lineage",
      link: "https://isogg.org/wiki/Haplogroup" },
    ydna: { term: "Y-DNA", full: "Y-chromosome DNA", aliases: ["Y chromosome", "Y chromosomes"],
      short: "Y-DNA — Y-chromosome DNA: DNA on the Y chromosome; its largely non-recombining portion traces a direct paternal lineage.",
      more: "Analysis requires usable Y sequence, not a gender label. A relative on the relevant paternal line may provide that lineage when your own data has no Y.", learn: "learn-ancestry.html#lineage" },
    mtdna: { term: "mtDNA", full: "Mitochondrial DNA", aliases: ["mitochondrial DNA"],
      short: "mtDNA — Mitochondrial DNA: the small circular genome inside mitochondria, usually inherited through the egg.",
      more: "The human mitochondrial reference is 16,569 bases long. It traces one maternal line; uneven depth, heteroplasmy and similar nuclear sequences can complicate calls.", learn: "learn-ancestry.html#lineage" },
    admixture: { term: "Ancestry proportions", aliases: ["ancestry proportions", "admixture"],
      short: "Ancestry proportions are model-estimated shares of your autosomal DNA resembling chosen reference groups.",
      more: "The numbers change with the panel, model and labels. They are not precise fractions of nationality, culture or every genealogical ancestor.", learn: "learn-ancestry.html#autosomal" },
    refpop: { term: "Reference populations", aliases: ["reference populations", "reference population"],
      short: "Reference populations are labelled groups of sampled people whose DNA is used for statistical comparison.",
      more: "Panels such as HGDP or 1000 Genomes sample only part of human diversity. A missing group can make the model assign DNA to the nearest available group instead.", learn: "learn-ancestry.html#autosomal" },
    kg1000: { term: "1000 Genomes", aliases: ["1000 Genomes Project"],
      short: "The 1000 Genomes Project is a public collection of human genetic variation from multiple sampled populations.",
      more: "The classic phase-3 panel has 2,504 people; later high-coverage resources include 3,202 samples. Check which release a tool uses rather than assuming panel sizes or markers match.", learn: "learn-ancestry.html#autosomal" },
    hgdp: { term: "HGDP", full: "Human Genome Diversity Project", aliases: ["Human Genome Diversity Project"],
      short: "HGDP — Human Genome Diversity Project: a research collection of genetic samples from dozens of populations worldwide.",
      more: "Used as an ancestry reference, not a complete catalogue of humanity. Small and uneven samples limit the precision of population comparisons.", learn: "learn-ancestry.html#autosomal" },
    interval: { term: "95% interval", aliases: ["95% intervals"],
      short: "A 95% interval is an uncertainty range calculated by a statistical method; its interpretation depends on that method.",
      more: "A confidence interval describes long-run coverage of the procedure; a credible interval describes model-based probability. Neither automatically includes bias from an unrepresentative ancestry panel.", learn: "learn-ancestry.html#limits" },
    annotation: { term: "Annotation", aliases: ["annotation", "annotate", "annotated", "annotating"],
      short: "Annotation adds database and model information to variants, such as gene names, predicted consequences and population frequencies.",
      more: "It makes a VCF easier to interpret, but adds no new read evidence. Resource versions, transcript choice and reference build affect the result.", learn: "learn-health.html#annotation" },
    clinvar: { term: "ClinVar", full: "Clinical Variation database", aliases: [],
      short: "ClinVar — Clinical Variation database: a public collection of submitted interpretations of variants in relation to health conditions.",
      more: "Check condition, review status, date and conflicting submissions. A pathogenic label does not prove you carry the variant accurately or have the associated condition.", learn: "learn-health.html#clinvar",
      link: "https://www.ncbi.nlm.nih.gov/clinvar/" },
    vep: { term: "VEP", full: "Ensembl Variant Effect Predictor", aliases: ["Variant Effect Predictor"],
      short: "VEP — Ensembl Variant Effect Predictor: software that predicts how a variant overlaps genes, transcripts and protein-coding sequence.",
      more: "Its consequences include missense and stop-gained, not diagnoses. Use a matching build and transcript cache; different transcripts can give different consequences.", learn: "learn-health.html#annotation",
      link: "https://www.ensembl.org/info/docs/tools/vep/index.html" },
    gnomad: { term: "gnomAD", full: "Genome Aggregation Database", aliases: [],
      short: "gnomAD — Genome Aggregation Database: a research database of observed variant counts and allele frequencies across large sequencing cohorts.",
      more: "Frequency helps assess how plausible a rare-disease interpretation is. Cohorts are not all healthy or equally representative, and absence can mean insufficient coverage, not pathogenicity.", learn: "learn-health.html#frequency",
      link: "https://gnomad.broadinstitute.org/" },
    af: { term: "AF", full: "Allele frequency", aliases: ["allele frequency", "allele frequencies"],
      short: "AF — Allele frequency: the fraction of counted chromosome copies in a dataset carrying a particular allele.",
      more: "1% means 1 in 100 observed copies, not necessarily 1 in 100 people. Check population, coverage and sample count; rare is not the same as harmful.", learn: "learn-health.html#frequency" },
    acmg: { term: "ACMG", full: "American College of Medical Genetics and Genomics", aliases: [],
      short: "ACMG — American College of Medical Genetics and Genomics: a professional organization that publishes genetics guidance.",
      more: "Its secondary-findings gene list and ACMG/AMP variant-classification framework serve different purposes. A list match is not a diagnosis or a substitute for clinical interpretation.", learn: "learn-health.html#clinvar" },
    cadd: { term: "CADD", full: "Combined Annotation Dependent Depletion", aliases: [],
      short: "CADD — Combined Annotation Dependent Depletion: a model-based score ranking variants by predicted deleteriousness.",
      more: "A scaled score of 20 is roughly the top 1% among scored possible substitutions, not a 99% probability of disease. Use it to prioritize investigation, not diagnose.", learn: "learn-health.html#scores" },
    revel: { term: "REVEL", full: "Rare Exome Variant Ensemble Learner", aliases: [],
      short: "REVEL — Rare Exome Variant Ensemble Learner: a score combining models to prioritize missense variants.",
      more: "Scores run from 0 to 1; higher suggests greater predicted impact. They are not calibrated personal disease probabilities and do not replace other evidence.", learn: "learn-health.html#scores" },
    spliceai: { term: "SpliceAI", full: "Splice-site Artificial Intelligence model", aliases: [],
      short: "SpliceAI is a neural-network model predicting whether a variant may change RNA splicing, the cutting and joining of a gene's RNA.",
      more: "Its delta scores prioritize possible splice changes. A predicted change is not proof it occurs in the relevant tissue or causes disease.", learn: "learn-health.html#scores" },
    alphamissense: { term: "AlphaMissense", aliases: [],
      short: "AlphaMissense is a machine-learning model that scores possible single-amino-acid substitutions in human proteins.",
      more: "It can help prioritize missense variants. It does not evaluate every variant type or establish an individual's diagnosis.", learn: "learn-health.html#scores" },
    pgx: { term: "PGx", full: "Pharmacogenomics", aliases: ["pharmacogenomics", "Pharmacogenomics"],
      short: "PGx — Pharmacogenomics: the study of how genetic variation influences response to medicines, including metabolism and adverse reactions.",
      more: "Gene-based prescribing guidance exists for some drugs, not all. Do not start, stop or change medication based on a personal genome report; discuss validated findings with a clinician or pharmacist.", learn: "learn-health.html#medicines" },
    pharmcat: { term: "PharmCAT", full: "Pharmacogenomics Clinical Annotation Tool", aliases: [],
      short: "PharmCAT — Pharmacogenomics Clinical Annotation Tool: software that translates genotypes into supported pharmacogenetic allele calls and guideline annotations.",
      more: "It needs correct build, alleles and reference evidence at defining sites. Missing or unsupported calls can change the inferred diplotype; a report is not a prescription.", learn: "learn-health.html#medicines" },
    hla: { term: "HLA", full: "Human leukocyte antigen", aliases: ["HLA typing"],
      short: "HLA — Human leukocyte antigen: a family of highly variable immune-system genes, mainly on chromosome 6, encoding cell-surface recognition proteins.",
      more: "Specialist tools estimate named HLA alleles. Transplant matching and drug safety decisions require appropriately validated clinical typing.", learn: "learn-health.html#medicines" },
    cyp2d6: { term: "CYP2D6", full: "Cytochrome P450 family 2 subfamily D member 6", aliases: [],
      short: "CYP2D6 — Cytochrome P450 family 2 subfamily D member 6: a gene encoding an enzyme that metabolizes many medicines.",
      more: "A similar neighbouring gene, deletions and extra copies complicate ordinary variant calls. Specialist analysis and clinical confirmation may be needed for medication decisions.", learn: "learn-health.html#medicines" },
    missense: { term: "Missense", aliases: ["missense"],
      short: "A missense variant changes a protein-coding DNA codon so that a different amino acid is predicted in the protein.",
      more: "Many have little effect, some are harmful, and some remain uncertain. A gene can have multiple transcripts, so the same DNA change may have different annotations.", learn: "learn-health.html#annotation" },
    pathogenic: { term: "Pathogenic", aliases: ["pathogenic", "likely pathogenic", "benign", "likely benign"],
      short: "Pathogenic is an evidence-based classification that a variant causes a specified condition in an appropriate genetic context; benign means non-disease-causing in that context.",
      more: "Interpretation also needs inheritance, zygosity, penetrance and trustworthy sequencing. A label alone is not a diagnosis, and submitters can disagree.", learn: "learn-health.html#clinvar" },
    vus: { term: "VUS", full: "Variant of uncertain significance", aliases: [],
      short: "VUS — Variant of uncertain significance: a variant for which evidence is insufficient or conflicting about a disease association.",
      more: "It is not a positive diagnosis and should not on its own direct medical management. Classifications can change as new evidence appears.", learn: "learn-health.html#clinvar" },
    staralleles: { term: "Star allele", aliases: ["star alleles", "star allele", "diplotype"],
      short: "A star allele is a named set of variants on one copy of a pharmacogene, such as CYP2C19*2; a diplotype is the pair of allele calls.",
      more: "Guidelines may link a diplotype to a metabolizer category. Missing defining sites, copy-number changes or uncertain phase can make a simple two-allele label misleading.", learn: "learn-health.html#medicines" },
    pgs: { term: "PGS", full: "Polygenic score", aliases: ["polygenic score", "polygenic scores"],
      short: "PGS — Polygenic score: a weighted sum of alleles at many sites, using effect estimates from a study of a trait.",
      more: "It can rank a sample against a specified population. A percentile is not an absolute disease risk; performance changes with ancestry, study design and environment.", learn: "learn-health.html#polygenic" },
    prs: { term: "PRS", full: "Polygenic risk score", aliases: [],
      short: "PRS — Polygenic risk score: a polygenic score intended to describe genetic predisposition to a disease.",
      more: "Relative genetic predisposition needs population-specific calibration and clinical factors to become an absolute risk estimate. It is not a diagnosis or destiny.", learn: "learn-health.html#polygenic" },
    methylation: { term: "Methylation", aliases: ["methylation", "methylated"],
      short: "DNA methylation is the attachment of a small chemical methyl group to a DNA base without changing its sequence.",
      more: "It can affect gene regulation. Suitable Nanopore or PacBio data may retain modification evidence; ordinary Illumina whole-genome FASTQ does not, and patterns vary by tissue and age.", learn: "learn-sequencing.html#platforms" },
    cpg: { term: "CpG", full: "Cytosine–phosphate–guanine", aliases: ["CpG sites"],
      short: "CpG — Cytosine–phosphate–guanine: a C followed by G along the same DNA strand, joined by a phosphate backbone.",
      more: "Many human methylation analyses measure modified cytosines at these sites. It does not mean a C/G base pair across the double helix.", learn: "learn-sequencing.html#platforms" },
    m5c: { term: "5mC", full: "5-methylcytosine", aliases: [],
      short: "5mC — 5-methylcytosine: a cytosine DNA base with a methyl group attached at its fifth carbon.",
      more: "Modification-aware sequencing models can estimate it. A detected modification is not itself a disease marker.", learn: "learn-sequencing.html#platforms" },
    igv: { term: "IGV", full: "Integrative Genomics Viewer", aliases: ["genome browser", "Integrative Genomics Viewer"],
      short: "IGV — Integrative Genomics Viewer: a genome-browser application that displays reads, variants and annotation tracks along genomic coordinates.",
      more: "Inspect indexed BAM/CRAM or VCF files against the matching build. Visual inspection can expose artifacts but does not confirm a diagnosis.", learn: "learn-variants.html#confidence" },
    gpu: { term: "GPU", full: "Graphics processing unit", aliases: ["GPUs"],
      short: "GPU — Graphics processing unit: a processor designed to run many similar calculations in parallel.",
      more: "Some basecallers and variant callers can use a supported GPU. An NVIDIA CUDA workflow does not automatically run on an Apple GPU; models, memory and software support must match.", learn: "learn-files.html#computing" },
    cpu: { term: "CPU", full: "Central processing unit", aliases: ["CPUs", "threads", "cores"],
      short: "CPU — Central processing unit: the computer's general-purpose processor; cores execute work and software threads divide tasks.",
      more: "More threads may speed analysis but consume more memory and compete for disk access. Doubling threads does not guarantee twice the speed.", learn: "learn-files.html#computing" },
    ram: { term: "RAM", full: "Random-access memory", aliases: [],
      short: "RAM — Random-access memory: the computer's fast working memory used while programs run.",
      more: "It is different from disk storage. Reference indexes and callers may need tens of GB; insufficient RAM can cause swapping or a failed run.", learn: "learn-files.html#computing" },
    cuda: { term: "CUDA", full: "Compute Unified Device Architecture", aliases: [],
      short: "CUDA — Compute Unified Device Architecture: NVIDIA's programming platform for running calculations on supported NVIDIA GPUs.",
      more: "A CUDA tool needs compatible GPU hardware, drivers and software. It is not the graphics interface used by Apple silicon.", learn: "learn-files.html#computing" },
    metal: { term: "Metal", aliases: [],
      short: "Metal is Apple's software interface for GPU graphics and parallel computation on supported Apple hardware.",
      more: "Only tools explicitly built for Metal can use it for analysis. Installing a CUDA-only tool does not make it run on Metal.", learn: "learn-files.html#computing" },
    docker: { term: "Docker", aliases: ["container", "containers"],
      short: "Docker is software that runs applications in containers: packaged programs with their user-space dependencies.",
      more: "Some genomics workflows use container images. Images can be large downloads; a container is not a guarantee of offline use or a security boundary for untrusted code.", learn: "learn-files.html#computing" },
    pixi: { term: "Pixi environment", aliases: ["Pixi", "pixi environment"],
      short: "A Pixi environment is a project-specific collection of pinned software packages managed by the Pixi package tool.",
      more: "It helps keep tool versions reproducible. WGS Extract checks required tools; a missing program must be installed separately, not silently by an analysis action.", learn: "learn-files.html#computing" },
    liftover: { term: "Liftover", aliases: ["liftover", "liftOver"],
      short: "Liftover translates genomic coordinates between two reference assemblies using a precomputed mapping.",
      more: "It does not realign the original reads. Some positions fail, map ambiguously or need allele transformations; validate the destination reference before interpreting results.", learn: "learn-reference.html#liftover" },
    chain: { term: "Chain file", aliases: ["chain file", "chain files"],
      short: "A chain file describes aligned blocks between two genome assemblies, used to map coordinates in a specified direction.",
      more: "Use the correct source and destination builds. Gaps and rearrangements mean not every variant can be transferred reliably.", learn: "learn-reference.html#liftover" },
    rna: { term: "RNA", full: "Ribonucleic acid", aliases: [],
      short: "RNA — Ribonucleic acid: a molecule copied from DNA that can carry protein-building instructions or perform other cellular functions.",
      more: "Whole-genome DNA sequencing does not directly measure which RNAs a tissue makes. Predicted effects on RNA need additional evidence.", learn: "learn-dna.html#genes" },
    transcript: { term: "Transcript", aliases: ["transcript", "transcripts"],
      short: "A transcript is an RNA sequence produced from a gene; one gene can produce multiple transcript versions.",
      more: "Annotation databases describe reference transcripts. A DNA variant can have different consequences in different transcripts, so record the transcript identifier and version.", learn: "learn-health.html#annotation" },
    splicing: { term: "Splicing", aliases: ["splicing", "splice site", "splice sites"],
      short: "Splicing removes sections called introns from RNA and joins retained sections called exons.",
      more: "Variants can disrupt this process or change which exons are included. A splice prediction is not proof of an effect in a particular tissue.", learn: "learn-health.html#scores" },
    frameshift: { term: "Frameshift", aliases: ["frameshift"],
      short: "A frameshift shifts the three-base reading frame of protein-coding sequence, usually through an insertion or deletion not divisible by three.",
      more: "A stop-gained variant instead introduces an early stop instruction. Both can disrupt a protein, but transcript choice and location affect interpretation.", learn: "learn-health.html#annotation" },
    recessive: { term: "Recessive", aliases: ["recessive", "carrier", "compound heterozygous"],
      short: "For an autosomal recessive condition, disease typically requires relevant disease-causing alleles on both copies of a gene.",
      more: "A carrier usually has one affected copy. Two different variants can be compound heterozygous when on opposite copies; phase and clinical interpretation matter.", learn: "learn-health.html#clinvar" },
    penetrance: { term: "Penetrance", aliases: ["penetrance"],
      short: "Penetrance is the proportion of people with a particular genotype who show an associated trait or condition.",
      more: "It can depend on age, environment and other genes. A pathogenic variant with reduced penetrance does not guarantee symptoms.", learn: "learn-health.html#clinvar" },
    mosaicism: { term: "Mosaicism", aliases: ["mosaicism", "mosaic"],
      short: "Mosaicism means different cells in one person carry different DNA sequence or chromosome complements.",
      more: "A blood or saliva sample may not reflect every tissue. Low-level mosaic variants can be hard to distinguish from artifacts and need specialist confirmation.", learn: "learn-variants.html#confidence" },
    par: { term: "PAR", full: "Pseudoautosomal region", aliases: ["pseudoautosomal", "pseudoautosomal regions"],
      short: "PAR — Pseudoautosomal region: a homologous region shared by X and Y chromosomes that can recombine.",
      more: "An XY sample usually has two copies of these regions even though much of X and Y is single-copy. Calling must use build-specific boundaries.", learn: "learn-variants.html#genotype" },
    adapter: { term: "Adapter", aliases: ["adapter", "adapters"],
      short: "An adapter is a short artificial DNA sequence attached during library preparation so a sequencer can process a fragment.",
      more: "Read-through adapters may appear at read ends and can be trimmed. Trimming too aggressively can remove useful sample sequence.", learn: "learn-sequencing.html#quality" },
    duplicate: { term: "Duplicate reads", aliases: ["duplicate reads", "duplicates"],
      short: "Duplicate reads are records suspected to represent repeated observations of the same original DNA fragment, often from amplification.",
      more: "Marking them can prevent overcounting evidence. Identical positions alone are not always proof of duplication, particularly for very deep or targeted data.", learn: "learn-sequencing.html#depth" },
    basecalling: { term: "Basecalling", aliases: ["basecalling", "basecaller", "basecalling model"],
      short: "Basecalling is software's conversion of sequencer signals into estimated DNA letters and base quality scores.",
      more: "For Nanopore, changing the model can change accuracy or modification calls. Re-basecalling may require original signal files that a FASTQ does not preserve.", learn: "learn-sequencing.html#sample" },
    freebayes: { term: "FreeBayes", aliases: [],
      short: "FreeBayes is a Bayesian small-variant caller that considers combinations of alleles across short stretches of aligned reads.",
      more: "It can provide an independent set of candidate calls. Disagreement with another caller is a reason to review evidence, not proof either caller is right.", learn: "learn-files.html#calling" },
    clair3: { term: "Clair3", aliases: [],
      short: "Clair3 is a machine-learning small-variant caller designed for long-read sequencing data.",
      more: "Choose a model matching the platform and chemistry. A model trained for different read errors can give misleading confidence.", learn: "learn-files.html#calling" },
    fastqc: { term: "FastQC", full: "FASTQ Quality Control", aliases: ["MultiQC", "fastp"],
      short: "FastQC — FASTQ Quality Control: software that summarizes read qualities, base composition and possible sequencing artifacts in FASTQ files.",
      more: "MultiQC combines tool reports; fastp can summarize and trim reads. A warning chart prompts investigation, not an automatic decision to discard or trim.", learn: "learn-sequencing.html#quality" },
    smn: { term: "SMN1 / SMN2", full: "Survival of motor neuron 1 / 2", aliases: ["SMN1", "SMN2"],
      short: "SMN1 and SMN2 — Survival of motor neuron 1 and 2: two very similar genes whose copy numbers and distinguishing variants require specialized analysis.",
      more: "SMN1 loss is associated with spinal muscular atrophy; ordinary small-variant calls may not resolve copies correctly. Personal sequencing is not a substitute for clinical carrier or diagnostic testing.", learn: "learn-health.html#medicines" },
    checksum: { term: "Checksum", aliases: ["checksum", "checksums", "SHA-256", "MD5"],
      full: "SHA-256: Secure Hash Algorithm 256-bit; MD5: Message-Digest Algorithm 5",
      short: "A checksum is a short value computed from file content, used to detect changes or verify an exact file match.",
      more: "Reference checksums help identify sequences and check downloads. A match verifies content against that value, not that a source is scientifically correct or trustworthy.", learn: "learn-reference.html#cram" },
    bcf: { term: "BCF", full: "Binary Call Format", aliases: [],
      short: "BCF — Binary Call Format: a binary encoding of VCF variant and genotype records.",
      more: "It is efficient for processing with bcftools, but many websites expect text VCF instead. Conversion does not add missing calls or read evidence.", learn: "learn-files.html#vcf" },
    tsv: { term: "TSV", full: "Tab-separated values", aliases: [],
      short: "TSV — Tab-separated values: a text table with columns separated by tab characters.",
      more: "Useful for result tables and spreadsheets. Automatic spreadsheet formatting can alter gene names or identifiers; retain an untouched original.", learn: "learn-files.html#reference" },
    parquet: { term: "Parquet", aliases: [],
      short: "Parquet is a compressed, column-oriented table format used for efficient analysis of large datasets.",
      more: "Some variant tables use it instead of TSV. It needs compatible software to read; it is not itself a genome or variant-calling standard.", learn: "learn-files.html#reference" },
    json: { term: "JSON", full: "JavaScript Object Notation", aliases: [],
      short: "JSON — JavaScript Object Notation: a text format of named fields, lists and values used for structured results and metadata.",
      more: "A result manifest can record outputs and provenance in JSON. It describes a run; it does not replace the genome files it lists.", learn: "learn-files.html#reference" },
    ssd: { term: "SSD", full: "Solid-state drive", aliases: ["SSDs"],
      short: "SSD — Solid-state drive: persistent storage using flash memory rather than spinning disks.",
      more: "Fast local SSD space helps alignment and sorting. Temporary working files can be much larger than the final result; free space is different from available RAM.", learn: "learn-files.html#computing" },
    qc: { term: "QC", full: "Quality control", aliases: [],
      short: "QC — Quality control: checks on data properties such as read quality, depth, contamination and sample identity.",
      more: "QC can flag problems before interpretation. Passing selected checks does not prove that every genotype is correct or make a run a clinical test.", learn: "learn-sequencing.html#quality" },
    acmgsf: { term: "ACMG SF", full: "American College of Medical Genetics and Genomics Secondary Findings", aliases: ["secondary findings"],
      short: "ACMG SF — American College of Medical Genetics and Genomics Secondary Findings: guidance on reporting selected actionable findings in clinical sequencing.",
      more: "The list names genes and condition-specific reporting criteria, not every harmful variant. Versions change; a personal software match is not a clinical secondary-finding assessment.", learn: "learn-health.html#clinvar" },
    cpic: { term: "CPIC", full: "Clinical Pharmacogenetics Implementation Consortium", aliases: [],
      short: "CPIC — Clinical Pharmacogenetics Implementation Consortium: a group publishing guidance on how to use genetic test results in prescribing.",
      more: "Guidelines help clinicians interpret validated pharmacogenetic findings. They do not mean every personal sequencing result is reliable or that you should change a medicine yourself.", learn: "learn-health.html#medicines" },
    amp: { term: "AMP", full: "Association for Molecular Pathology", aliases: [],
      short: "AMP — Association for Molecular Pathology: a professional organization that co-published widely used clinical variant-interpretation guidance with ACMG.",
      more: "The ACMG/AMP framework weighs different kinds of evidence. Automated application is not equivalent to a clinical laboratory's expert review.", learn: "learn-health.html#clinvar" },
    stopgained: { term: "Stop-gained", aliases: ["stop-gained", "nonsense"],
      short: "A stop-gained variant introduces a premature stop instruction into a protein-coding sequence.",
      more: "It may shorten a protein or lead to RNA breakdown. Transcript choice, location and gene mechanism matter; the label alone does not establish disease.", learn: "learn-health.html#annotation" },
  };
  Object.keys(terms).forEach(function (key) {
    if (!terms[key].learn) terms[key].learn = "learn.html#term-" + key;
  });
  WGSM.v2terms.terms = terms;
})();
